const whapi = $json.whapi ?? {};
const type = String(whapi.type ?? '').toLowerCase();
const mime = String(whapi.mime_type ?? '').toLowerCase();
const filename = String(whapi.filename ?? '').toLowerCase();
const text = String(whapi.text_body ?? '').trim();

let tipo_operacional = 'outro';

if (['text', 'chat', 'conversation'].includes(type) || text.length > 0) {
  tipo_operacional = 'texto';
}

if (['audio', 'voice', 'ptt'].includes(type) || mime.startsWith('audio/')) {
  tipo_operacional = 'audio';
}

if (
  ['image', 'document', 'file', 'video'].includes(type) ||
  mime.startsWith('image/') ||
  mime.includes('pdf') ||
  filename.length > 0
) {
  tipo_operacional = 'arquivo_comprovante';
}

return {
  json: {
    ...$json,
    processamento: {
      tipo_operacional,
      type_original: type,
      mime_type: mime,
      filename,
      tem_texto: text.length > 0,
      texto: text
    }
  }
};

