const whapi = $json.whapi ?? {};
const media = whapi.media ?? {};
const binary = $binary?.data;

function extFromMime(mime) {
  const m = String(mime ?? '').toLowerCase();

  if (m.includes('jpeg') || m.includes('jpg')) return 'jpg';
  if (m.includes('png')) return 'png';
  if (m.includes('webp')) return 'webp';
  if (m.includes('pdf')) return 'pdf';
  if (m.includes('heic')) return 'heic';

  return 'bin';
}

function cleanName(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w.-]+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 120);
}

const mimeType =
  whapi.mime_type ||
  media.mime_type ||
  binary?.mimeType ||
  'application/octet-stream';

const ext = extFromMime(mimeType);

const originalFilename =
  media.filename ||
  whapi.filename ||
  binary?.fileName ||
  '';

const fileName = originalFilename
  ? cleanName(originalFilename)
  : cleanName([
      'cobranca',
      $json.contato?.cliente_id,
      $json.contato?.cliente_contato_id,
      whapi.message_id
    ].filter(Boolean).join('_')) + `.${ext}`;

const isImage = String(mimeType).startsWith('image/');
const isPdf = String(mimeType).includes('pdf') || fileName.toLowerCase().endsWith('.pdf');

let tipo_analise = 'nao_suportado';

if (isImage) tipo_analise = 'imagem';
if (isPdf) tipo_analise = 'pdf';

return {
  json: {
    ...$json,
    arquivo: {
      tipo_analise,
      file_name: fileName,
      mime_type: mimeType,
      extension: ext,
      source_url: media.url ?? null,
      media_id: media.id ?? null,
      caption: media.caption ?? whapi.text_body ?? '',
      binary_property: 'data',
      pode_analisar_ia: ['imagem', 'pdf'].includes(tipo_analise)
    }
  },
  binary: $binary
};

