const base = $node["Preparar mídia para análise IA"].json;
const upload = $node["HTTP | OpenAI upload arquivo"].json;

// Nome correto do seu node de download
const downloadItems = $items("HTTP | Baixar mídia Whapi");

if (!downloadItems?.[0]?.binary?.data) {
  throw new Error('Binary data não encontrado no node HTTP | Baixar mídia Whapi');
}

const originalBinary = {
  data: downloadItems[0].binary.data
};

let parsed = null;

try {
  const text = $json.output?.[0]?.content?.[0]?.text;

  if (typeof text === 'object' && text !== null) {
    parsed = text;
  } else if (typeof text === 'string') {
    parsed = JSON.parse(text);
  }
} catch (error) {
  parsed = null;
}

if (!parsed) {
  parsed = {
    classificacao_ia: 'INCONCLUSIVO',
    tipo_documento: 'desconhecido',
    valor_extraido_centavos: null,
    data_extraida: null,
    autenticacao: null,
    favorecido: null,
    pagador: null,
    confianca: 'baixa',
    observacoes: 'Falha ao normalizar análise da IA.'
  };
}

const classificacao = String(parsed.classificacao_ia ?? 'INCONCLUSIVO').toUpperCase();

return {
  json: {
    ...base,

    openai_file: {
      id: upload.id,
      object: upload.object,
      filename: upload.filename,
      purpose: upload.purpose,
      bytes: upload.bytes,
      status: upload.status
    },

    comprovante_ia: {
      classificacao_ia: ['COMPROVANTE_PROVAVEL', 'NAO_COMPROVANTE', 'INCONCLUSIVO'].includes(classificacao)
        ? classificacao
        : 'INCONCLUSIVO',

      tipo_documento: parsed.tipo_documento ?? 'desconhecido',
      valor_extraido_centavos: parsed.valor_extraido_centavos ?? null,
      data_extraida: parsed.data_extraida ?? null,
      autenticacao: parsed.autenticacao ?? null,
      favorecido: parsed.favorecido ?? null,
      pagador: parsed.pagador ?? null,
      confianca: parsed.confianca ?? 'baixa',
      observacoes: parsed.observacoes ?? ''
    },

    openai_response_raw: $json
  },
  binary: originalBinary
};

